import React, { useState, useEffect } from 'react';

const Autocomplete = ({ suggestions, onSelect }) => {
  const [inputValue, setInputValue] = useState('');
  const [filteredSuggestions, setFilteredSuggestions] = useState([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(-1);

  useEffect(() => {
    const filterSuggestions = () => {
      const filtered = suggestions.filter((suggestion) => {
        return suggestion.toLowerCase().includes(inputValue.toLowerCase());
      });
      setFilteredSuggestions(filtered);
    };

    filterSuggestions();
  }, [inputValue, suggestions]);

  const handleInputChange = (event) => {
    setInputValue(event.target.value);
  };

  const handleSuggestionClick = (suggestion) => {
    onSelect(suggestion);
    setInputValue('');
  };

  const handleArrowKey = (event) => {
    if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
      const newIndex = activeSuggestionIndex + (event.key === 'ArrowDown' ? 1 : -1);
      if (newIndex >= 0 && newIndex < filteredSuggestions.length) {
        setActiveSuggestionIndex(newIndex);
      }
    }
  };

  const renderSuggestions = () => {
    if (activeSuggestionIndex >= 0 && filteredSuggestions.length > 0) {
      const suggestion = filteredSuggestions[activeSuggestionIndex];
      return (
        <div
          className="suggestion"
          onMouseDown={() => handleSuggestionClick(suggestion)}
          onClick={() => handleSuggestionClick(suggestion)}
          onKeyDown={handleArrowKey}
          aria-label={suggestion}
          role="option"
        >
          {suggestion}
        </div>
      );
    }
  };

  return (
    <div>
      <input
        type="text"
        value={inputValue}
        onChange={handleInputChange}
        placeholder="Type to autocomplete..."
      />
      {renderSuggestions()}
    </div>
  );
};

export default Autocomplete;
```
This component takes in two props:

* `suggestions`: an array of strings that will be used for autocomplete suggestions
* `onSelect`: a function that will be called when a suggestion is selected

The component uses three state variables:

* `inputValue`: the current value of the input field
* `filteredSuggestions`: the filtered list of suggestions based on the input value
* `activeSuggestionIndex`: the index of the currently active suggestion

The component also uses two effects:

* `useEffect` to filter the suggestions based on the input value
* `useEffect` to set the active suggestion index when the input value changes

The component renders an input field and a list of suggestions. When the user types in the input field, the component filters the suggestions and updates the list. When the user clicks on a suggestion, the `onSelect` function is called with the selected suggestion.

